player.x += direction.x;
player.y -= direction.y;
console.log(player);

function move(player, dx, dy, speed, dt, width, height) {
  const length = Math.hypot(dx, dy) || 1;
  player.x = Math.max(0, Math.min(width, player.x + dx / length * speed * dt));
  player.y = Math.max(0, Math.min(height, player.y + dy / length * speed * dt));
}
const p = { x: 2, y: 2 };
move(p, 1, 0, 10, 0.5, 10, 10);
console.log(p);

function overlaps(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x &&
         a.y < b.y + b.h && a.y + a.h > b.y;
}
const player = { x: 1, y: 1, w: 2, h: 2 };
const coin = { x: 2, y: 2, w: 1, h: 1 };
console.log(overlaps(player, coin));

const game = { score: 0, status: 'playing' };
function collect(item) {
  if (!item.collected) { item.collected = true; game.score += 10; }
}
collect({ collected: false });
console.log(`${game.status}: ${game.score}`);

function clamp(value, min, max) { return Math.max(min, Math.min(max, value)); }
console.assert(clamp(-2, 0, 10) === 0, 'lower bound');
console.assert(clamp(12, 0, 10) === 10, 'upper bound');
